USE pasarkita;
CREATE TABLE IF NOT EXISTS integration_outbox (id BIGINT AUTO_INCREMENT PRIMARY KEY,event_id VARCHAR(128) NOT NULL UNIQUE,event_type VARCHAR(100) NOT NULL,aggregate_id INT NOT NULL,payload JSON NOT NULL,status ENUM('pending','published','failed','dead_letter') NOT NULL DEFAULT 'pending',attempts INT NOT NULL DEFAULT 0,max_attempts INT NOT NULL DEFAULT 8,last_error VARCHAR(500),available_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,published_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_outbox(status,available_at));
CREATE TABLE IF NOT EXISTS integration_inbox (id BIGINT AUTO_INCREMENT PRIMARY KEY,event_id VARCHAR(128) NOT NULL UNIQUE,event_type VARCHAR(100) NOT NULL,payload JSON NOT NULL,processed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS shipments (id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL UNIQUE,tracking_reference VARCHAR(64) NOT NULL UNIQUE,status ENUM('created','assigned','dispatched','in_transit','delivered','failed','cancelled') NOT NULL,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
